import { Button, Card, Input, Stack, Stepper, Text } from '@jinx-ui/react';

export interface RegistrationValues {
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
}

interface RegistrationFormProps {
  onSubmit: (values: RegistrationValues) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY: RegistrationValues = {
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);

  const setField =
    (field: keyof RegistrationValues) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setValues((prev) => ({ ...prev, [field]: value }));
    };

  const isLast = step === STEPS.length - 1;

  return (
    <Card>
      <Stack direction="column" gap="var(--jx-space-lg)">
        <Stepper activeStep={step}>
          {STEPS.map((label, index) => (
            <Stepper.Step key={label} index={index} label={label} />
          ))}
        </Stepper>

        {step === 0 && (
          <Stack direction="column" gap="var(--jx-space-md)">
            <Input
              label="Email"
              type="email"
              value={values.email}
              onChange={setField('email')}
            />
            <Input
              label="Телефон"
              type="tel"
              value={values.phone}
              onChange={setField('phone')}
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="var(--jx-space-md)">
            <Input label="Город" value={values.city} onChange={setField('city')} />
            <Input label="Улица, дом" value={values.street} onChange={setField('street')} />
            <Input label="Индекс" value={values.zip} onChange={setField('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="var(--jx-space-sm)">
            <Text variant="body">Email: {values.email}</Text>
            <Text variant="body">Телефон: {values.phone}</Text>
            <Text variant="body">Город: {values.city}</Text>
            <Text variant="body">Улица, дом: {values.street}</Text>
            <Text variant="body">Индекс: {values.zip}</Text>
          </Stack>
        )}

        <Stack direction="row" gap="var(--jx-space-sm)" justify="space-between">
          <Button
            variant="secondary"
            disabled={step === 0}
            onClick={() => setStep((prev) => prev - 1)}
          >
            Назад
          </Button>
          <Button
            variant="primary"
            onClick={() => (isLast ? onSubmit(values) : setStep((prev) => prev + 1))}
          >
            {isLast ? 'Отправить' : 'Дальше'}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
